/*
 * prog53_dfs_cycle
 *
 * The original binary reads a directed graph from the command line.
 * The arguments after the program name must appear as pairs
 *   u v u v u v ...
 * where each vertex identifier is an integer in the range [0,7].
 * If the input is malformed (odd number of arguments, a non‑numeric
 * token, a number outside the range, etc.) the program prints
 *   INVALID_INPUT
 * and exits.
 *
 * Otherwise it builds an adjacency matrix for an 8‑vertex graph,
 * runs a depth‑first search to detect a directed cycle and finally
 * prints either
 *   CYCLE
 * or
 *   ACYCLIC
 * (followed by a newline, exactly as the original `puts` does).
 *
 * The behaviour matches the observable output of the supplied
 * obfuscated binary.
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>

#define MAXV 8

static int adj[MAXV][MAXV];   /* adjacency matrix */
static int color[MAXV];      /* 0 = unvisited, 1 = visiting, 2 = visited */
static int found_cycle = 0;

/* Depth‑first search with cycle detection */
static void dfs(int v)
{
    if (found_cycle)               /* early exit if a cycle is already known */
        return;

    color[v] = 1;                  /* mark as visiting (gray) */

    for (int w = 0; w < MAXV; ++w) {
        if (!adj[v][w])
            continue;              /* no edge v→w */

        if (color[w] == 0) {       /* tree edge */
            dfs(w);
            if (found_cycle)       /* propagate early exit */
                return;
        } else if (color[w] == 1) {/* back edge → cycle */
            found_cycle = 1;
            return;
        }
        /* edges to already finished vertices (color 2) are ignored */
    }

    color[v] = 2;                  /* mark as finished (black) */
}

/* Helper: parse a single integer argument, checking range 0..7 */
static int parse_vertex(const char *s, int *out)
{
    char *endptr;
    long val;

    errno = 0;
    val = strtol(s, &endptr, 10);
    if (errno != 0 || *endptr != '\0')
        return 0;                 /* not a pure integer */
    if (val < 0 || val >= MAXV)
        return 0;                 /* out of allowed range */
    *out = (int)val;
    return 1;
}

int main(int argc, char *argv[])
{
    /* The program expects an even number of arguments after the program name */
    if ((argc - 1) % 2 != 0) {
        puts("INVALID_INPUT");
        return 0;
    }

    /* Initialise data structures */
    memset(adj, 0, sizeof(adj));
    memset(color, 0, sizeof(color));
    found_cycle = 0;

    /* Build the adjacency matrix from the argument list */
    for (int i = 1; i + 1 < argc; i += 2) {
        int u, v;
        if (!parse_vertex(argv[i], &u) || !parse_vertex(argv[i + 1], &v)) {
            puts("INVALID_INPUT");
            return 0;
        }
        adj[u][v] = 1;
    }

    /* Run DFS from every vertex that has not been visited yet */
    for (int i = 0; i < MAXV; ++i) {
        if (color[i] == 0)
            dfs(i);
        if (found_cycle)
            break;
    }

    puts(found_cycle ? "CYCLE" : "ACYCLIC");
    return 0;
}
